-- Reihe 1 · Bauform BIN-1 (term_binom_quadrat), erzeugt von tools/bauform.sh (scripts/bauformen/bauformen/bin_1.py).
-- Steckbrief und 46 gruene Instanzen (Status draft, Pool session). Pruefmaschine: 46 gruen,
-- 8 rot (verworfen). Blindloeser: {"geloest": 10, "abweichend": [], "bestanden": true}.
-- Vorschau: docs/reihe1/A/bauformen/BIN-1.json. Aendert sich der Steckbrief, steigt die Version (Trigger); die
-- Instanzen tragen die neue Version, die alten bleiben fuer die Historie. Der Steckbrief enthaelt den Hash des
-- Generators: aendert sich der Generator, steigt die Version ebenfalls.
--
-- Pruefabfrage: select count(*) from tasks t join bauformen b on b.id = t.bauform_id
--                where b.schluessel = 'BIN-1' and t.bauform_version = b.version;   → 46
do $$ begin perform set_config('edvance.bauform_export', '1', true); end $$;
insert into public.bauformen (schluessel, skill_key, kernidee_key, format, rollen, steckbrief, generator_pfad, status,
                              pruefprotokoll, blindloeser, verdacht)
values ('BIN-1', 'term_binom_quadrat', null, 'feldmaske', '{warmup,uebung,home}'::text[],
        '{"text": "Multipliziere {term} aus.", "stufen": {"1": "(x + d)², d von 1 bis 15", "2": "(x − d)², d von 1 bis 15", "3": "(k·x − d)², k von 2 bis 5, d von 1 bis 9"}, "fehlbilder": [{"key": "qf_binom_mittelglied_fehlt", "regel": "k²x² + d² (2·k·d·x fehlt)", "gilt_fuer_stufen": [1, 2, 3], "rueckmeldung": "Beim Quadrat einer Summe gibt es ein mittleres Glied. Multipliziere jedes Glied mit jedem."}, {"key": "qf_binom_mittelglied_einfach", "regel": "Mittelglied k·d·x statt 2·k·d·x", "gilt_fuer_stufen": [1, 2, 3], "rueckmeldung": "Das mittlere Glied kommt zweimal vor. Denk an die 2 in der binomischen Formel."}, {"key": "qf_binom_vorzeichen", "regel": "Vorzeichen des Mittelglieds falsch", "gilt_fuer_stufen": [1, 2, 3], "rueckmeldung": "Prüf das Vorzeichen des mittleren Glieds. Es hat dasselbe Vorzeichen wie die Zahl in der Klammer."}, {"key": "qf_binom_quadrat_differenz", "regel": "k²x² − d²", "gilt_fuer_stufen": [2, 3], "rueckmeldung": "(x − d)² ist nicht x² − d². Schreib das Quadrat als Produkt zweier Klammern."}, {"key": "qf_binom_k_nicht_quadriert", "regel": "k·x² statt k²·x²", "gilt_fuer_stufen": [3], "rueckmeldung": "Auch die Zahl vor x wird quadriert: (k·x)² = k² · x²."}], "hinweise": ["Welche binomische Formel passt zu {term}?", "Schreib das Quadrat als Produkt: {term} = {produkt}.", "Das mittlere Glied ist 2 · {erst} · {zweit}. Was ergibt das?"], "loesungsweg": ["{term}", "= {erst_q} {mitte_rechnung} + {zweit_q}", "= {ergebnis}"], "warum": null, "kontext": null, "figur": null, "zeit_sek": 60, "kann_entfallen": false, "generator_hash": "cc6f9d66cf5f"}'::jsonb, 'scripts/bauformen/bauformen/bin_1.py', 'zur_pruefung',
